fn rsplit(a: Vec<String>, sep: String, maxsplit: u8) -> Vec<Vec<String>> {
    // sep is guaranteed non-empty by the problem statement.
    let mut out: Vec<Vec<String>> = Vec::with_capacity(a.len());

    for s in a {
        if maxsplit == 0 {
            // No splitting performed.
            out.push(vec![s]);
            continue;
        }

        if s.is_empty() {
            // Empty input yields a single empty string.
            out.push(vec![String::new()]);
            continue;
        }

        // Perform at most `maxsplit` right splits:
        // splitting into at most `maxsplit + 1` parts.
        let parts: Vec<String> = s
            .rsplitn((maxsplit as usize) + 1, &sep)
            .map(|p| p.to_string())
            .collect();

        // rsplitn returns parts from right-to-left; reverse to restore left-to-right order.
        let mut parts = parts;
        parts.reverse();

        // Ensure inner list is non-empty (rsplitn always yields at least one part).
        if parts.is_empty() {
            parts.push(s);
        }

        out.push(parts);
    }

    out
}